import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    INF = float('inf')
    b = [int(x) if x != b'-1' else INF for x in data[1:n+1]]

    for i in range(1, n):
        v = b[i-1] + 1
        if v < b[i]:
            b[i] = v

    for i in range(n-2, -1, -1):
        v = b[i+1] + 1
        if v < b[i]:
            b[i] = v

    sys.stdout.write(' '.join(map(str, b)))

main()
